	this.initialize(mode,startPosition,loop,{A:491,B:686,C:732,D:1054});

	// timeline functions:
	this.frame_1 = function() {
		window.parent['audio19242'+'Object'].actionPlay();
	}
	this.frame_6 = function() {
		var _this = this;
		createjs.Touch.enable(stage);
		var arr = ['A', 'B', 'C', 'D', 'E', 'F'];
		
		for (var i = 1; i <= 4; i++) {
			_this['anniu' + i].mouseChildren = false;
		}
		
		_this.addEventListener("click", function (e) {
			if (e.target.name) {
				if (e.target.name.indexOf("anniu") >= 0) {
		
					var curNum = Number(e.target.name.substring(5));
					//console.log(curNum)
					_this.gotoAndPlay(arr[curNum - 1]);
					window.parent['audio19242' + 'Object'].actionStop();
					window.parent['audio112816' + 'Object'].actionStop();
					window.parent['audio112816' + 'Object'].actionStop();
					window.parent['audio151834' + 'Object'].actionStop();
					window.parent['audio151841' + 'Object'].actionStop();
					window.parent['audio151855' + 'Object'].actionStop();
				}
			}
		});
	}
	this.frame_509 = function() {
		window.parent['audio112914'+'Object'].actionPlay();
	}
	this.frame_528 = function() {
		var _this = this;
		_this.stop();
		//多选题 
		var arr1 = [];
		
		createjs.Touch.enable(stage);
		var arr = ['A', 'B', 'C', 'D', 'E', 'F'];
		
		_this.daan.visible = false;
		_this.jixu.visible = false;
		var btnNum = 4;
		for (var i = 1; i <= btnNum; i++) {
			_this['btn_' + i].mouseChildren = false;
			_this['show' + i].visible = false;
		}
		
		var Array1 = ['未回答'];
		
		
		var win = window;
		while (win !== win.parent && win.VarQuestion_0036 === undefined && win.VarNurseA14 === undefined) {
			win = win.parent;
		}
		
		
		var answerArr = {
			1: 'A',
			2: 'B',
			3: 'C',
			4: 'D',
			5: 'E',
			6: 'F',
			7: 'G'
		}
		var flag = true;
		
		_this.addEventListener("click", function (e) {
			if (e.target.name) {
				if (e.target.name.indexOf("btn_") >= 0 && flag) {
		
					var curNum = Number(e.target.name.substring(4))
					//console.log(curNum)
		
		
					var index = arr1.indexOf(curNum);
					if (index == -1) {
						arr1.push(curNum);
						_this['show' + curNum].visible = true;
					} else {
						arr1.splice(index, 1);
						_this['show' + curNum].visible = false;
					}
					playSound('click');
				} else if (e.target.name.indexOf("queding") >= 0) {
					flag = false;
					arr1.sort(function (a, b) {
						return a - b;
					});
					_this.queding.visible = false;
					_this.daan.visible = true;
					_this.jixu.visible = true;
					if (arr1.toString() == '1,2,4') {
						playSound('correct');
		
						_this.daan.gotoAndStop(0);
						win.VarNurseA14.set(3); //设置护士A 1题变量的得分
					} else {
						_this.daan.gotoAndStop(1);
						playSound('error');
		
						win.VarNurseA14.set(0); //设置护士A 1题变量的得分
					}
		
		
					if (arr1.length == 0) {
		
						win.VarQuestion_0036.set(Array1.toString());
					} else {
						Array1.length = 0;
						for (var i = 1; i <= arr1.length; i++) {
		
							Array1.push(answerArr[arr1[i - 1]]);
						}
						win.VarQuestion_0036.set(Array1.join('、'));
					}
		
					//console.log(Array1.toString())
		
				} else if (e.target.name.indexOf("jixu") >= 0) {
					playSound('click');
					_this.play();
					window.parent['audio112914' + 'Object'].actionStop();
		
				}
			}
		});
	}
